styles:
/* Apex Report — SchoolPilot report card, one term per card.
   Written for the PDF renderer (dompdf): tables for layout (no flexbox or
   grid), solid colours (no gradients), no shadows, no web fonts, no SVG. */

body { font-family: "DejaVu Sans", sans-serif; color: #22303F; font-size: 8.3pt; line-height: 1.22; }
.sheet { width: 100%; }
table { border-collapse: collapse; width: 100%; }
td, th { vertical-align: middle; }

/* ---------- masthead ---------- */
.mast { background: #12294E; color: #fff; }
.mast td { padding: 2.6mm 4mm 5.5mm; }
.mast-crest { width: 17mm; }
.crest { width: 15mm; }
.mast .crest td { border-radius: 7.5mm; background: #fff; height: 14mm; padding: 0; text-align: center; vertical-align: middle; color: #12294E;
                  font-family: "DejaVu Serif", serif; font-weight: bold; font-size: 11pt; }
.crest-img { width: 15mm; height: 15mm; }
.mast h1 { font-family: "DejaVu Serif", serif; font-size: 12.5pt; margin: 0; letter-spacing: 0.2px; line-height: 1.15; }
.contact { font-size: 6.8pt; color: #C8D4E8; margin-top: 1mm; }
.mast-term { text-align: right; width: 42mm; }
.term-pill { background: #C9A227; color: #12294E; font-weight: bold; font-size: 7.4pt; padding: 1.4mm 3mm; border-radius: 3mm; letter-spacing: 0.8px; }
.session { font-size: 7.6pt; margin-top: 2.2mm; letter-spacing: 1.6px; color: #EACB6A; font-weight: bold; }

/* ---------- student card ---------- */
.student { margin-top: -5mm; background: #fff; border: 1px solid #E4E9F2; }
.student td { padding: 1.8mm 3.5mm; }
.photo-cell { width: 18mm; }
.photo { width: 15mm; }
.student .photo td { border-radius: 7.5mm; background: #E8EDF5; height: 14mm; padding: 0; text-align: center; vertical-align: middle; color: #12294E; font-weight: bold; font-size: 10pt; }
.photo-img { width: 16mm; height: 16mm; border: 2px solid #12294E; }
.sname { font-family: "DejaVu Serif", serif; font-size: 12.5pt; font-weight: bold; color: #12294E; }
.chips { margin-top: 0.8mm; }
.chip { display: inline-block; font-size: 6.3pt; font-weight: bold; padding: 0.5mm 2mm; border-radius: 2.5mm;
        background: #F1F5FB; color: #12294E; border: 1px solid #E4E9F2; margin: 0.6mm 1mm 0 0; }
.chip.gold { background: #C9A227; border-color: #C9A227; color: #12294E; }
.next { text-align: right; font-size: 6.8pt; color: #64748B; width: 36mm; }
.next b { display: block; color: #12294E; font-size: 8.4pt; margin-top: 0.6mm; }

/* ---------- section titles ---------- */
.sec { margin: 2.4mm 0 1.4mm; border-bottom: 1.5px solid #C9A227; padding-bottom: 0.4mm; }
.kicker { color: #C9A227; font-weight: bold; font-size: 5.6pt; letter-spacing: 1.6px; font-family: "DejaVu Sans", sans-serif; margin-left: 2mm; }
.sec h2 { font-family: "DejaVu Serif", serif; color: #12294E; font-size: 10.5pt; margin: 0; line-height: 1.2; }

/* ---------- at a glance ---------- */
.dash td { width: 25%; padding: 0 1.2mm; vertical-align: top; }
.dash td:first-child { padding-left: 0; }
.dash td:last-child { padding-right: 0; }
.card { border: 1px solid #E4E9F2; border-radius: 2.5mm; padding: 1.6mm 2.6mm; background: #FDFEFF; }
.card h3 { margin: 0 0 1mm; font-size: 5.9pt; letter-spacing: 1.3px; color: #64748B; }
.bignum { font-size: 13pt; font-weight: bold; color: #12294E; }
.bignum small { font-size: 8pt; color: #64748B; }
.substats { font-size: 6.5pt; color: #64748B; margin-top: 0.6mm; }
.substats b { color: #12294E; }
.rate { color: #C9A227; font-size: 5.8pt; font-weight: bold; margin-top: 1mm; }
.std-head { font-size: 5.8pt; font-weight: bold; letter-spacing: 1.2px; color: #64748B; margin: 1mm 0 0.4mm; }
.scores th .max { font-weight: normal; font-size: 5.4pt; color: #C8D4E8; }

/* ---------- subject table ---------- */
.scores { font-size: 7.6pt; }
.scores th { background: #12294E; color: #fff; font-size: 6pt; letter-spacing: 0.5px; padding: 1.4mm 1mm; text-align: center; }
.scores th.subj, .scores td.subj { text-align: left; }
.scores td { border-bottom: 1px solid #E4E9F2; padding: 0.55mm 1mm; text-align: center; line-height: 1.1; }
.scores td.subj { font-weight: bold; }
.scores .num { width: 6mm; color: #64748B; }
.scores tr.group td { background: #EDF2FA; color: #12294E; font-weight: bold; font-size: 6pt; letter-spacing: 1.5px; text-align: left; padding: 0.8mm 2mm; }
.scores td.total { font-weight: bold; }
.scores td.empty { color: #64748B; font-style: italic; padding: 4mm; }
.remark { font-weight: normal; font-style: italic; font-size: 6.6pt; color: #64748B; margin-top: 0.4mm; }
.scores tr.avg td { background: #FFF8E3; font-weight: bold; color: #12294E; border-top: 2px solid #C9A227; }

/* total shaded by band of ten (score_band filter) */
.sb-90 { background: #CDEBDA; color: #075E36; }
.sb-80 { background: #E4F4EB; color: #0E7C4A; }
.sb-70 { background: #FCF0CF; color: #8A6100; }
.sb-60 { background: #FCE4CE; color: #A34A00; }
.sb-50, .sb-40 { background: #F9D9D9; color: #8F1D1D; }
.sb-below40 { background: #F3C9C9; color: #7A1414; }

/* ---------- grade pills (grade_key filter) ---------- */
.gp, .kc { background: #64748B; color: #fff; font-weight: bold; }
.gp { display: inline-block; min-width: 6.5mm; padding: 0 1mm; border-radius: 1.2mm; font-size: 6.6pt; line-height: 1.35; text-align: center; }
.gp.big { font-size: 9pt; min-width: 7mm; padding: 0.4mm 1.2mm; margin-left: 1.5mm; }
.kc { display: inline-block; font-size: 6pt; padding: 0.3mm 2mm; border-radius: 2.5mm; margin-right: 1mm; }
/* Letter scales (A, B+, B, C, D, E, F) */
.gk-A, .gk-Aplus { background: #0E7C4A; }
.gk-Aminus, .gk-Bplus { background: #3E9E63; }
.gk-B { background: #C08A00; }
.gk-Bminus, .gk-Cplus, .gk-C { background: #C2601B; }
.gk-D { background: #C0392B; }
.gk-E, .gk-F { background: #8F1D1D; }
/* WAEC nine-point scale */
.gk-A1 { background: #0E7C4A; }
.gk-B2, .gk-B3 { background: #3E9E63; }
.gk-C4, .gk-C5, .gk-C6 { background: #C08A00; }
.gk-D7, .gk-E8 { background: #C2601B; }
.gk-F9 { background: #8F1D1D; }

/* ---------- standards ---------- */
.twocol > tbody > tr > td, .twocol > tr > td { vertical-align: top; width: 50%; }
.twocol td.left { padding-right: 3mm; }
.twocol td.right { padding-left: 3mm; }
.std td { padding: 0.4mm 1mm; border-bottom: 1px dashed #E4E9F2; font-size: 7.3pt; }
.keylist td { padding: 0.3mm 1mm; font-size: 7.1pt; border-bottom: 1px dashed #E4E9F2; }
.keylist td.kg { width: 11mm; }
.keylist td.kr { width: 18mm; color: #64748B; }
.std-rating { text-align: right; width: 14mm; }
.rating-pill { background: #F1F5FB; color: #12294E; font-weight: bold; font-size: 6.6pt; padding: 0 2mm; border-radius: 2mm; }

/* ---------- key ---------- */
.keys { line-height: 1.95; }

/* ---------- comments / signatures ---------- */
.signrow { margin-top: 2.4mm; }
.sig { width: 42%; padding-right: 5mm; vertical-align: bottom; }
.sig .lbl { font-size: 5.9pt; font-weight: bold; letter-spacing: 1.2px; color: #64748B; }
.sig .write { min-height: 7mm; padding: 0.5mm 0.5mm; font-size: 7.4pt; font-style: italic; color: #33415A; border-bottom: 1.5px solid #12294E; }
.sig .line { border-bottom: 1.5px solid #12294E; height: 4mm; }
.sig .who { font-size: 6pt; font-weight: bold; letter-spacing: 1px; color: #64748B; margin-top: 0.6mm; }
.stamp-cell { width: 20mm; }
.stamp { width: 17mm; }
.stamp td { border-radius: 8.5mm; border: 2px dashed #B7C2D4; height: 15mm; padding: 0; text-align: center; vertical-align: middle; color: #9AA7BC; font-size: 5pt; font-weight: bold; letter-spacing: 0.8px; }

/* ---------- verification / footer ---------- */
.verify { margin-top: 2.2mm; background: #F4F7FC; border: 1px solid #E4E9F2; }
.verify td { padding: 1mm 3mm; }
.verify .qr { width: 16mm; }
.verify .qr img { width: 14mm; height: 14mm; }
.vt { font-size: 6.8pt; color: #64748B; }
.vt b { color: #12294E; }
.vt .url { font-size: 6pt; color: #94A3B8; }
.foot { margin-top: 2mm; background: #12294E; color: #C8D4E8; font-size: 6.3pt; letter-spacing: 0.9px; }
.foot td { padding: 1.3mm 4mm; }
.foot td.r { text-align: right; color: #EACB6A; }
